-- | WebAssembly text format (WAT) code generator for Awsum 'Core'.
--
-- Produces human-readable WAT (S-expression syntax) used for
-- @awsum build -t wasm@ output and snapshot tests.
-- The binary @.wasm@ is generated by 'Awsum.Codegen.WASM.Assemble'.
--
-- Design:
--   * All values are @i32@ (pointers into linear memory).
--   * Strings are null-terminated bytes in linear memory (like LLVM).
--   * WASI provides I\/O: @fd_write@ for stdout, @args_get@ for CLI args.
--   * Bump allocator for dynamic memory (concat results).
--   * @funcref@ table + @call_indirect@ for higher-order functions.
module Awsum.Codegen.WASM (codegenWASM) where

import Awsum.Core
import Awsum.HM (rowTag)
import Awsum.Syntax (Name, Type' (..), noSpan)
import Data.Char qualified as Char
import Data.Map.Strict qualified as Map
import Data.Set qualified as Set
import Data.Text qualified as T
import Relude

-- ════════════════════════════════════════════════════════════════════════════
-- Public API
-- ════════════════════════════════════════════════════════════════════════════

-- | Produce a complete WAT module from a Core program.
codegenWASM :: CoreProgram -> Text
codegenWASM prog@(CoreProgram decls) =
  let (pool, emptyOff, heapStart) = buildStringPool prog
      valNames = Set.fromList [n | CValDef n _ <- decls]
      funNames = Set.fromList [n | CFunDef n _ _ <- decls]
      arities = Map.fromList [(n, length as) | CFunDef n as _ <- decls]
      funDefs = [n | CFunDef n _ _ <- decls]
      tableMap = Map.fromList (zip funDefs [0 :: Int ..])
      indirectArities = collectIndirectArities (CoreProgram decls) funNames
      ctx =
        WasmCtx
          { wParams = Set.empty,
            wValDefs = valNames,
            wFunDefs = funNames,
            wArities = arities,
            wStringPool = pool,
            wTableMap = tableMap,
            wIndirectArities = indirectArities,
            wLocalExprs = Map.empty,
            wConDepth = 0
          }
   in T.intercalate
        "\n"
        [ header,
          imports,
          memory,
          global heapStart,
          dataSection pool,
          table (length funDefs),
          elemSection funDefs,
          typeDecls indirectArities,
          runtimeHelpers emptyOff (usedBuiltIns prog) (usesIntLit prog),
          T.intercalate "\n\n" (map (emitDecl ctx) decls),
          "",
          startFunc,
          ")"
        ]

-- ════════════════════════════════════════════════════════════════════════════
-- Context
-- ════════════════════════════════════════════════════════════════════════════

data WasmCtx = WasmCtx
  { wParams :: Set Text,
    wValDefs :: Set Text,
    wFunDefs :: Set Text,
    wArities :: Map Text Int,
    wStringPool :: Map Text Int,
    wTableMap :: Map Text Int,
    wIndirectArities :: Set Int,
    wLocalExprs :: Map Text Text, -- case-bound variable → inline WAT expression
    wConDepth :: Int -- nesting depth for $__con_N locals
  }

-- ════════════════════════════════════════════════════════════════════════════
-- String pool
-- ════════════════════════════════════════════════════════════════════════════

-- | Offset where string constants begin in linear memory.
scratchSize :: Int
scratchSize = 64

-- | Build a string pool with byte offsets.
--   Always includes "" for __get_arg fallback.
--   Returns (pool, empty_string_offset, heap_start).
buildStringPool :: CoreProgram -> (Map Text Int, Int, Int)
buildStringPool (CoreProgram decls) =
  let strs = ordNub $ "" : concatMap stringsInDecl decls
      offsets = scanl (\off s -> off + byteLen s + 1) scratchSize strs
      pool = Map.fromList (zip strs offsets)
      emptyOff = fromMaybe scratchSize (Map.lookup "" pool)
      heapStart = fromMaybe scratchSize $ viaNonEmpty Relude.last (zipWith (\s o -> o + byteLen s + 1) strs offsets)
   in (pool, emptyOff, heapStart)

-- | Byte length of a string. Currently all strings are ASCII,
--   so T.length == byte length. When multi-byte UTF-8 is supported,
--   this should use Data.Text.Encoding.encodeUtf8 + BS.length.
byteLen :: Text -> Int
byteLen = T.length

stringsInDecl :: CDecl -> [Text]
stringsInDecl = \case
  CFunDef _ _ body -> stringsInExpr body
  CValDef _ rhs -> stringsInExpr rhs

stringsInExpr :: CExpr -> [Text]
stringsInExpr = \case
  CString s -> [s]
  CVar _ -> []
  CIntLit _ _ -> []
  CBuiltIn _ -> []
  CCon _ fields -> concatMap stringsInExpr fields
  CCase scrut alts -> stringsInExpr scrut <> concatMap (\(_, _, body) -> stringsInExpr body) alts
  CRow _ v -> stringsInExpr v
  CRowCase scrut alts -> stringsInExpr scrut <> concatMap (\(_, _, body) -> stringsInExpr body) alts
  CCall f xs -> stringsInExpr f <> concatMap stringsInExpr xs
  CLoop b -> stringsInExpr b
  CContinue xs -> concatMap stringsInExpr xs

-- | Collect arities used in indirect calls (CCall where callee is a param, not a known fun/prim).
collectIndirectArities :: CoreProgram -> Set Text -> Set Int
collectIndirectArities (CoreProgram decls) funNames =
  Set.fromList $ concatMap (collectInDecl funNames) decls
  where
    collectInDecl :: Set Text -> CDecl -> [Int]
    collectInDecl fns = \case
      CFunDef _ args body -> collectInExpr fns (Set.fromList args) body
      CValDef _ rhs -> collectInExpr fns Set.empty rhs

    collectInExpr :: Set Text -> Set Text -> CExpr -> [Int]
    collectInExpr fns params = \case
      CCall f xs ->
        let fromF = case f of
              CVar n | n `Set.member` params -> [length xs]
              _ -> []
            fromChildren = collectInExpr fns params f <> concatMap (collectInExpr fns params) xs
         in fromF <> fromChildren
      _ -> []

-- ════════════════════════════════════════════════════════════════════════════
-- Module sections (text)
-- ════════════════════════════════════════════════════════════════════════════

header :: Text
header =
  unlines
    [ ";; Awsum WASM codegen — WAT text format for inspection.",
      ";; Binary .wasm is generated by assembleWASM for execution.",
      "(module"
    ]

imports :: Text
imports =
  unlines
    [ "  (import \"wasi_snapshot_preview1\" \"fd_write\" (func $fd_write (param i32 i32 i32 i32) (result i32)))",
      "  (import \"wasi_snapshot_preview1\" \"args_sizes_get\" (func $args_sizes_get (param i32 i32) (result i32)))",
      "  (import \"wasi_snapshot_preview1\" \"args_get\" (func $args_get (param i32 i32) (result i32)))"
    ]

memory :: Text
memory = "  (memory (export \"memory\") 1)"

global :: Int -> Text
global heapStart = "  (global $heap (mut i32) (i32.const " <> show heapStart <> "))"

dataSection :: Map Text Int -> Text
dataSection pool
  | Map.null pool = ""
  | otherwise =
      T.intercalate "\n"
        $ map emitData (sortWith snd $ Map.toList pool)
  where
    emitData (s, off) =
      "  (data (i32.const " <> show off <> ") " <> watString s <> ")"

-- | Format a string for WAT data section (includes null terminator).
watString :: Text -> Text
watString s = "\"" <> watEscape s <> "\\00\""

-- | Escape a string for WAT syntax.
watEscape :: Text -> Text
watEscape = T.concatMap escChar
  where
    escChar c
      | c == '\\' = "\\\\"
      | c == '"' = "\\22"
      | c == '\n' = "\\0a"
      | c == '\t' = "\\09"
      | c == '\r' = "\\0d"
      | c == '\0' = "\\00"
      | Char.isPrint c = one c
      | otherwise =
          let n = Char.ord c
              hi = n `div` 16
              lo = n `mod` 16
              hexChar x
                | x < 10 = chr (Char.ord '0' + x)
                | otherwise = chr (Char.ord 'a' + x - 10)
           in "\\" <> toText [hexChar hi, hexChar lo]

table :: Int -> Text
table n
  | n == 0 = ""
  | otherwise = "  (table " <> show n <> " funcref)"

elemSection :: [Text] -> Text
elemSection fns
  | null fns = ""
  | otherwise =
      "  (elem (i32.const 0) " <> T.intercalate " " (map (\n -> "$" <> mangle n) fns) <> ")"

typeDecls :: Set Int -> Text
typeDecls arities
  | Set.null arities = ""
  | otherwise =
      T.intercalate "\n"
        $ map emitType (Set.toAscList arities)
  where
    emitType arity =
      "  (type $arity_"
        <> show arity
        <> " (func"
        <> (if arity > 0 then " (param" <> T.concat (replicate arity " i32") <> ")" else "")
        <> " (result i32)))"

-- ════════════════════════════════════════════════════════════════════════════
-- Runtime helpers
-- ════════════════════════════════════════════════════════════════════════════

-- | Emit only the runtime helpers referenced in Core. @__alloc@ /
--   @__strlen@ / @__memcpy@ / @__get_arg@ are always needed (the last
--   feeds argv into main; the rest are small infrastructure), the
--   higher-level helpers (@__concat@, @__print@, @__box_i32@,
--   @__show_i32@, @__predInt32@) are gated on usage.
runtimeHelpers :: Int -> Set Name -> Bool -> Text
runtimeHelpers emptyOff builtIns hasIntLit =
  let lns =
        filter
          (not . T.null)
          [ rtStrlen,
            rtAlloc,
            rtMemcpy,
            if Set.member "concatString" builtIns then rtConcat else "",
            if Set.member "IO.Stdout.print" builtIns then rtPrint else "",
            if hasIntLit then rtBoxI32 else "",
            if any (`Set.member` builtIns) ["showInt32", "showUInt8"]
              then rtShowI32
              else "",
            if Set.member "showUInt32" builtIns then rtShowU32 else "",
            if Set.member "predInt32" builtIns then rtPredI32 else "",
            if Set.member "predUInt8" builtIns then rtPredU8 else "",
            if Set.member "predUInt32" builtIns then rtPredU32 else "",
            if Set.member "succInt32" builtIns then rtSuccI32 else "",
            if Set.member "succUInt8" builtIns then rtSuccU8 else "",
            if Set.member "succUInt32" builtIns then rtSuccU32 else "",
            if any (`Set.member` builtIns) ["eqInt32", "eqUInt8", "eqUInt32"] then rtEqI32 else "",
            if Set.member "addInt32" builtIns then rtAddI32 else "",
            if Set.member "subInt32" builtIns then rtSubI32 else "",
            if Set.member "mulInt32" builtIns then rtMulI32 else "",
            if Set.member "negInt32" builtIns then rtNegI32 else "",
            if Set.member "addUInt8" builtIns then rtAddU8 else "",
            if Set.member "subUInt8" builtIns then rtSubU8 else "",
            if Set.member "mulUInt8" builtIns then rtMulU8 else "",
            if Set.member "addUInt32" builtIns then rtAddU32 else "",
            if Set.member "subUInt32" builtIns then rtSubU32 else "",
            if Set.member "mulUInt32" builtIns then rtMulU32 else "",
            if Set.member "splitOnFirst" builtIns then rtSplitOnFirst else "",
            if Set.member "parseInt32" builtIns then rtParseInt32 else "",
            if Set.member "parseUInt8" builtIns then rtParseUInt8 else "",
            if Set.member "parseUInt32" builtIns then rtParseUInt32 else "",
            rtGetArg emptyOff
          ]
   in T.intercalate "\n\n" lns

rtStrlen :: Text
rtStrlen =
  unlines
    [ "  (func $__strlen (param $s i32) (result i32)",
      "    (local $len i32)",
      "    (local.set $len (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        (br_if $break (i32.eqz (i32.load8_u (i32.add (local.get $s) (local.get $len)))))",
      "        (local.set $len (i32.add (local.get $len) (i32.const 1)))",
      "        (br $loop)))",
      "    (local.get $len))"
    ]

rtAlloc :: Text
rtAlloc =
  unlines
    [ "  (func $__alloc (param $size i32) (result i32)",
      "    (local $ptr i32)",
      "    (local.set $ptr (i32.and (i32.add (global.get $heap) (i32.const 3)) (i32.const -4)))",
      "    (global.set $heap (i32.add (local.get $ptr) (local.get $size)))",
      "    ;; Grow until the heap fits. A single 'memory.grow 1' is not",
      "    ;; enough when a single allocation (or the cumulative demand",
      "    ;; of a CPS-defunc'd non-tail recursion) overshoots by more",
      "    ;; than one page. Trap on grow failure (memory.grow returns -1",
      "    ;; at the wasm32 4 GiB cap or any engine memory limit) — OOM",
      "    ;; surfaces as an immediate wasm trap instead of an infinite",
      "    ;; loop in the allocator.",
      "    (block $grow_done",
      "      (loop $grow_loop",
      "        (br_if $grow_done",
      "          (i32.le_u (global.get $heap)",
      "                    (i32.mul (memory.size) (i32.const 65536))))",
      "        (if (i32.eq (memory.grow (i32.const 1)) (i32.const -1))",
      "          (then (unreachable)))",
      "        (br $grow_loop)))",
      "    (local.get $ptr))"
    ]

rtMemcpy :: Text
rtMemcpy =
  unlines
    [ "  (func $__memcpy (param $dst i32) (param $src i32) (param $len i32)",
      "    (local $i i32)",
      "    (local.set $i (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        (br_if $break (i32.ge_u (local.get $i) (local.get $len)))",
      "        (i32.store8 (i32.add (local.get $dst) (local.get $i))",
      "                    (i32.load8_u (i32.add (local.get $src) (local.get $i))))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $loop))))"
    ]

rtConcat :: Text
rtConcat =
  unlines
    [ "  (func $__concat (param $a i32) (param $b i32) (result i32)",
      "    (local $la i32) (local $lb i32) (local $buf i32)",
      "    (local.set $la (call $__strlen (local.get $a)))",
      "    (local.set $lb (call $__strlen (local.get $b)))",
      "    (local.set $buf (call $__alloc (i32.add (i32.add (local.get $la) (local.get $lb)) (i32.const 1))))",
      "    (call $__memcpy (local.get $buf) (local.get $a) (local.get $la))",
      "    (call $__memcpy (i32.add (local.get $buf) (local.get $la)) (local.get $b) (local.get $lb))",
      "    (i32.store8 (i32.add (local.get $buf) (i32.add (local.get $la) (local.get $lb))) (i32.const 0))",
      "    (local.get $buf))"
    ]

rtPrint :: Text
rtPrint =
  unlines
    [ "  (func $__print (param $s i32) (result i32)",
      "    (local $len i32)",
      "    (local.set $len (call $__strlen (local.get $s)))",
      "    (i32.store (i32.const 0) (local.get $s))",
      "    (i32.store (i32.const 4) (local.get $len))",
      "    (drop (call $fd_write (i32.const 1) (i32.const 0) (i32.const 1) (i32.const 8)))",
      "    (i32.const 0))"
    ]

-- | Box a 32-bit value as a heap cell; the returned pointer is the uniform
--   representation of both Int32 and UInt8 at runtime (UInt8 values 0..255
--   fit trivially in 32 bits, which avoids a second boxing variant).
rtBoxI32 :: Text
rtBoxI32 =
  unlines
    [ "  (func $__box_i32 (param $v i32) (result i32)",
      "    (local $p i32)",
      "    (local.set $p (call $__alloc (i32.const 4)))",
      "    (i32.store (local.get $p) (local.get $v))",
      "    (local.get $p))"
    ]

-- | Render a boxed integer as a decimal null-terminated string.
--
--   The input pointer holds a 32-bit value; we treat it as signed (@i32.lt_s@)
--   for the minus-sign check. UInt8 values 0..255 are always positive in the
--   signed interpretation, so the same routine renders them correctly.
--
--   Algorithm: write digits into a 16-byte scratch buffer starting at the
--   second-to-last byte and moving left. 11 digits (@-2147483648@) + null
--   terminator is the worst case, which comfortably fits.
--
--   Negation of @INT_MIN@ is a no-op in two's complement, but since we use
--   @i32.div_u@ / @i32.rem_u@ on the magnitude, the unsigned reading of
--   @0x80000000@ is @2147483648@ — the correct magnitude.
rtShowI32 :: Text
rtShowI32 =
  unlines
    [ "  (func $__show_i32 (param $p i32) (result i32)",
      "    (local $v i32) (local $buf i32) (local $pos i32) (local $neg i32) (local $mag i32) (local $digit i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (local.set $buf (call $__alloc (i32.const 16)))",
      "    (i32.store8 (i32.add (local.get $buf) (i32.const 15)) (i32.const 0))",
      "    (local.set $pos (i32.const 14))",
      "    (if (i32.lt_s (local.get $v) (i32.const 0))",
      "      (then",
      "        (local.set $neg (i32.const 1))",
      "        (local.set $mag (i32.sub (i32.const 0) (local.get $v))))",
      "      (else",
      "        (local.set $neg (i32.const 0))",
      "        (local.set $mag (local.get $v))))",
      "    (if (i32.eqz (local.get $mag))",
      "      (then",
      "        (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.const 48))",
      "        (local.set $pos (i32.sub (local.get $pos) (i32.const 1))))",
      "      (else",
      "        (block $done",
      "          (loop $loop",
      "            (br_if $done (i32.eqz (local.get $mag)))",
      "            (local.set $digit (i32.rem_u (local.get $mag) (i32.const 10)))",
      "            (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.add (local.get $digit) (i32.const 48)))",
      "            (local.set $pos (i32.sub (local.get $pos) (i32.const 1)))",
      "            (local.set $mag (i32.div_u (local.get $mag) (i32.const 10)))",
      "            (br $loop)))))",
      "    (if (local.get $neg)",
      "      (then",
      "        (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.const 45))",
      "        (local.set $pos (i32.sub (local.get $pos) (i32.const 1)))))",
      "    (i32.add (local.get $buf) (i32.add (local.get $pos) (i32.const 1))))"
    ]

-- | predInt32: Int32 -> Either UnderflowError Int32.
--   Containers follow the uniform WASM layout [i32 tag at offset 0,
--   i32 fields at offsets 4, 8, ...]. Tags: Left=0, Right=1,
--   UnderflowError=0. Returns `Left UnderflowError` on INT32_MIN,
--   `Right (v - 1)` otherwise.
rtPredI32 :: Text
rtPredI32 =
  unlines
    [ "  (func $__predInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eq (local.get $v) (i32.const -2147483648))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | predUInt8: UInt8 -> Either UnderflowError UInt8.
--   Mirrors 'rtPredI32' but checks against 0 and subtracts without
--   masking — (v - 1) is in 0..254 when v >= 1, so it stays in UInt8
--   range naturally. Container layout and tag assignment match
--   'rtPredI32' exactly.
rtPredU8 :: Text
rtPredU8 =
  unlines
    [ "  (func $__predUInt8 (param $p i32) (result i32)",
      "    (local $v i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eqz (local.get $v))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | succInt32: Int32 -> Either OverflowError Int32.
--   Mirror of 'rtPredI32' with the boundary at INT32_MAX and addition
--   instead of subtraction. OverflowError is single-constructor, so its
--   inner-box tag is 0 (same as UnderflowError), which matches the
--   predecessor helpers' encoding exactly.
rtSuccI32 :: Text
rtSuccI32 =
  unlines
    [ "  (func $__succInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eq (local.get $v) (i32.const 2147483647))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.add (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | succUInt8: UInt8 -> Either OverflowError UInt8.
--   Mirrors 'rtSuccI32' but checks against 255. Masking is unnecessary —
--   (v + 1) is in 1..255 when v <= 254, so the result stays in UInt8 range
--   naturally.
rtSuccU8 :: Text
rtSuccU8 =
  unlines
    [ "  (func $__succUInt8 (param $p i32) (result i32)",
      "    (local $v i32) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eq (local.get $v) (i32.const 255))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.add (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | addInt32: Int32 -> Int32 -> Either (UnderflowError | OverflowError) Int32.
--   Signed overflow detected with the XOR trick: '(a ^ sum) & (b ^ sum)'
--   has its sign bit set iff signed addition overflowed. Direction is
--   read off 'a >= 0' so a single 'i32.ge_s 0' picks 'OverflowError'
--   (positive overflow) vs 'UnderflowError' (negative). Sum is computed
--   in i32 and wraps modulo 2^32 — that's exactly the value the XOR
--   check needs. Three boxes on the err path: inner @CCon@ (UE / OE
--   single ctor, tag 0), row wrap (tag = FNV-1a of label name), Either
--   @Left@ wrap (tag 0). Mirrors what surface @Left UnderflowError@
--   would lower to.
-- | FNV-1a 32-bit row tags for the prelude's nominal labels used by
--   the Int32 arithmetic builtins. Computed via 'rowTag' so the
--   runtime helpers stay in lockstep with 'Awsum.HM.canonicalLabel'.
underflowTag :: Text
underflowTag = show (rowTag (TyCon noSpan "UnderflowError"))

overflowTag :: Text
overflowTag = show (rowTag (TyCon noSpan "OverflowError"))

rtAddI32 :: Text
rtAddI32 =
  unlines
    [ "  (func $__addInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $a i32) (local $b i32) (local $s i32)",
      "    (local $inner i32) (local $row i32) (local $box i32) (local $cell i32)",
      "    (local.set $a (i32.load (local.get $pa)))",
      "    (local.set $b (i32.load (local.get $pb)))",
      "    (local.set $s (i32.add (local.get $a) (local.get $b)))",
      "    (if (result i32)",
      "      (i32.lt_s",
      "        (i32.and",
      "          (i32.xor (local.get $a) (local.get $s))",
      "          (i32.xor (local.get $b) (local.get $s)))",
      "        (i32.const 0))",
      "      (then",
      "        (local.set $inner (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $inner) (i32.const 0))",
      "        (local.set $row (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $row)",
      "          (if (result i32) (i32.ge_s (local.get $a) (i32.const 0))",
      "            (then (i32.const " <> overflowTag <> "))",
      "            (else (i32.const " <> underflowTag <> "))))",
      "        (i32.store offset=4 (local.get $row) (local.get $inner))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $row))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (local.get $s))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | addUInt8: UInt8 -> UInt8 -> Either OverflowError UInt8.
--   Both operands are 0..255 so an i32 add gives 0..510 and a single
--   'i32.gt_u 255' check selects the branch — no widening needed beyond
--   the already-i32-typed cells, no mask on the ok path.
rtAddU8 :: Text
rtAddU8 =
  unlines
    [ "  (func $__addUInt8 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $s i32) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $s (i32.add (i32.load (local.get $pa)) (i32.load (local.get $pb))))",
      "    (if (result i32) (i32.gt_u (local.get $s) (i32.const 255))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (local.get $s))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | subInt32: Int32 -> Int32 -> Either (UnderflowError | OverflowError) Int32.
--   Signed-subtraction overflow detected with the XOR trick:
--   '(a ^ b) & (a ^ diff) < 0' holds iff signed subtraction overflowed.
--   Direction is read off 'a >= 0' (when subtraction overflows the signs
--   of @a@ and @b@ must differ, so @a >= 0@ implies @b < 0@ which implies
--   positive overflow → OverflowError). Same row-tagged error encoding
--   as 'rtAddI32'.
rtSubI32 :: Text
rtSubI32 =
  unlines
    [ "  (func $__subInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $a i32) (local $b i32) (local $d i32)",
      "    (local $inner i32) (local $row i32) (local $box i32) (local $cell i32)",
      "    (local.set $a (i32.load (local.get $pa)))",
      "    (local.set $b (i32.load (local.get $pb)))",
      "    (local.set $d (i32.sub (local.get $a) (local.get $b)))",
      "    (if (result i32)",
      "      (i32.lt_s",
      "        (i32.and",
      "          (i32.xor (local.get $a) (local.get $b))",
      "          (i32.xor (local.get $a) (local.get $d)))",
      "        (i32.const 0))",
      "      (then",
      "        (local.set $inner (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $inner) (i32.const 0))",
      "        (local.set $row (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $row)",
      "          (if (result i32) (i32.ge_s (local.get $a) (i32.const 0))",
      "            (then (i32.const " <> overflowTag <> "))",
      "            (else (i32.const " <> underflowTag <> "))))",
      "        (i32.store offset=4 (local.get $row) (local.get $inner))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $row))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (local.get $d))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | mulInt32: Int32 -> Int32 -> Either (UnderflowError | OverflowError) Int32.
--   Promote both operands to i64, multiply at 64-bit width, range-check
--   the result against [INT32_MIN, INT32_MAX]. Direction (over vs under)
--   is read off the lcmp result — i64.gt_s → OverflowError, i64.lt_s →
--   UnderflowError. The truncated i32 product is the correct ok-path
--   value when the comparison falls through. Same row-tagged error
--   encoding as 'rtAddI32'.
rtMulI32 :: Text
rtMulI32 =
  unlines
    [ "  (func $__mulInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $p i64)",
      "    (local $inner i32) (local $row i32) (local $box i32) (local $cell i32)",
      "    (local.set $p",
      "      (i64.mul",
      "        (i64.extend_i32_s (i32.load (local.get $pa)))",
      "        (i64.extend_i32_s (i32.load (local.get $pb)))))",
      "    (if (result i32) (i64.gt_s (local.get $p) (i64.const 2147483647))",
      "      (then",
      "        (local.set $inner (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $inner) (i32.const 0))",
      "        (local.set $row (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $row) (i32.const " <> overflowTag <> "))",
      "        (i32.store offset=4 (local.get $row) (local.get $inner))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $row))",
      "        (local.get $cell))",
      "      (else",
      "        (if (result i32) (i64.lt_s (local.get $p) (i64.const -2147483648))",
      "          (then",
      "            (local.set $inner (call $__alloc (i32.const 4)))",
      "            (i32.store (local.get $inner) (i32.const 0))",
      "            (local.set $row (call $__alloc (i32.const 8)))",
      "            (i32.store (local.get $row) (i32.const " <> underflowTag <> "))",
      "            (i32.store offset=4 (local.get $row) (local.get $inner))",
      "            (local.set $cell (call $__alloc (i32.const 8)))",
      "            (i32.store (local.get $cell) (i32.const 0))",
      "            (i32.store offset=4 (local.get $cell) (local.get $row))",
      "            (local.get $cell))",
      "          (else",
      "            (local.set $box (call $__alloc (i32.const 4)))",
      "            (i32.store (local.get $box) (i32.wrap_i64 (local.get $p)))",
      "            (local.set $cell (call $__alloc (i32.const 8)))",
      "            (i32.store (local.get $cell) (i32.const 1))",
      "            (i32.store offset=4 (local.get $cell) (local.get $box))",
      "            (local.get $cell))))))"
    ]

-- | negInt32: Int32 -> Either OverflowError Int32.
--   Mirrors 'rtSuccI32' but checks against INT32_MIN and uses
--   '(0 - v)' for the ok branch. OverflowError is single-constructor,
--   so its inner-box tag is 0 — Left-branch encoding is identical
--   to predInt32.
rtNegI32 :: Text
rtNegI32 =
  unlines
    [ "  (func $__negInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eq (local.get $v) (i32.const -2147483648))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (i32.const 0) (local.get $v)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | subUInt8: UInt8 -> UInt8 -> Either UnderflowError UInt8.
--   Both operands are 0..255 so the i32 difference is in -255..255 and a
--   single 'i32.lt_s 0' check selects the underflow branch. No mask on
--   the ok path — when a >= b the difference is already a valid UInt8.
rtSubU8 :: Text
rtSubU8 =
  unlines
    [ "  (func $__subUInt8 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $d i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $d (i32.sub (i32.load (local.get $pa)) (i32.load (local.get $pb))))",
      "    (if (result i32) (i32.lt_s (local.get $d) (i32.const 0))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (local.get $d))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | mulUInt8: UInt8 -> UInt8 -> Either OverflowError UInt8.
--   Both operands are 0..255 so an i32 multiply gives 0..65025 — well
--   inside i32 range. A single 'i32.gt_u 255' check selects the branch.
rtMulU8 :: Text
rtMulU8 =
  unlines
    [ "  (func $__mulUInt8 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $p i32) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $p (i32.mul (i32.load (local.get $pa)) (i32.load (local.get $pb))))",
      "    (if (result i32) (i32.gt_u (local.get $p) (i32.const 255))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (local.get $p))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | splitOnFirst: String -> String -> Maybe (Tuple2 String String).
--   WASM has no built-in substring search, so we hand-roll a byte-by-byte
--   scan: outer 'i' loop walks `0..str_len - sep_len`, inner 'j' loop
--   compares `sep[j]` against `str[i + j]` until either a mismatch
--   (advance i) or full match (capture pos, break). Empty separator is
--   handled implicitly: the inner loop runs zero times, $match stays 1,
--   the first iteration of the outer loop returns position 0. Separator
--   longer than `str` is also implicit: the outer loop's bound check
--   fails on the first iteration, returning Nothing.
--   Container layout matches the rest of this file:
--     Maybe Nothing : 1-slot cell [tag=0]
--     Maybe Just    : 2-slot cell [tag=1, payload]
--     Tuple2        : 3-slot cell [tag=0, prefix, suffix]
rtSplitOnFirst :: Text
rtSplitOnFirst =
  unlines
    [ "  (func $__splitOnFirst (param $sep i32) (param $str i32) (result i32)",
      "    (local $sep_len i32) (local $str_len i32)",
      "    (local $i i32) (local $j i32) (local $pos i32) (local $match i32)",
      "    (local $prefix i32) (local $suffix i32) (local $tuple i32) (local $cell i32)",
      "    (local $suf_len i32)",
      "    (local.set $sep_len (call $__strlen (local.get $sep)))",
      "    (local.set $str_len (call $__strlen (local.get $str)))",
      "    (local.set $pos (i32.const -1))",
      "    (local.set $i (i32.const 0))",
      "    (block $break",
      "      (loop $loop",
      "        ;; if i + sep_len > str_len: not found, break",
      "        (br_if $break",
      "          (i32.gt_u",
      "            (i32.add (local.get $i) (local.get $sep_len))",
      "            (local.get $str_len)))",
      "        ;; check whether sep matches at position i",
      "        (local.set $j (i32.const 0))",
      "        (local.set $match (i32.const 1))",
      "        (block $check_break",
      "          (loop $check_loop",
      "            (br_if $check_break (i32.eq (local.get $j) (local.get $sep_len)))",
      "            (if (i32.ne",
      "                  (i32.load8_u (i32.add (local.get $str) (i32.add (local.get $i) (local.get $j))))",
      "                  (i32.load8_u (i32.add (local.get $sep) (local.get $j))))",
      "              (then",
      "                (local.set $match (i32.const 0))",
      "                (br $check_break)))",
      "            (local.set $j (i32.add (local.get $j) (i32.const 1)))",
      "            (br $check_loop)))",
      "        (if (local.get $match)",
      "          (then",
      "            (local.set $pos (local.get $i))",
      "            (br $break)))",
      "        (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "        (br $loop)))",
      "    (if (result i32) (i32.eq (local.get $pos) (i32.const -1))",
      "      (then",
      "        (local.set $cell (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (local.get $cell))",
      "      (else",
      "        ;; prefix = str[0..pos], freshly allocated, null-terminated",
      "        (local.set $prefix (call $__alloc (i32.add (local.get $pos) (i32.const 1))))",
      "        (call $__memcpy (local.get $prefix) (local.get $str) (local.get $pos))",
      "        (i32.store8 (i32.add (local.get $prefix) (local.get $pos)) (i32.const 0))",
      "        ;; suffix = str[pos + sep_len..], freshly allocated, null-terminated",
      "        (local.set $suf_len (i32.sub (i32.sub (local.get $str_len) (local.get $pos)) (local.get $sep_len)))",
      "        (local.set $suffix (call $__alloc (i32.add (local.get $suf_len) (i32.const 1))))",
      "        (call $__memcpy",
      "          (local.get $suffix)",
      "          (i32.add (local.get $str) (i32.add (local.get $pos) (local.get $sep_len)))",
      "          (local.get $suf_len))",
      "        (i32.store8 (i32.add (local.get $suffix) (local.get $suf_len)) (i32.const 0))",
      "        ;; Tuple2 cell: [tag=0, prefix, suffix]",
      "        (local.set $tuple (call $__alloc (i32.const 12)))",
      "        (i32.store (local.get $tuple) (i32.const 0))",
      "        (i32.store offset=4 (local.get $tuple) (local.get $prefix))",
      "        (i32.store offset=8 (local.get $tuple) (local.get $suffix))",
      "        ;; Just cell: [tag=1, tuple]",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $tuple))",
      "        (local.get $cell))))"
    ]

-- | parseInt32 : String -> Either ParseError Int32. Handrolled byte
--   scan; same algorithm as the LLVM, JVM, and CLR helpers — i64
--   accumulator capped at the magnitude `|minInt32|`. The constant
--   2147483648 is built with the shift trick `1 << 31` (avoids needing
--   a separate i64 literal in the binary). On any failure path we set
--   the `$failed` flag and `br $exit` out of the parsing block; result
--   construction (Right or Left) happens after the block based on the
--   flag.
rtParseInt32 :: Text
rtParseInt32 =
  unlines
    [ "  (func $__parseInt32 (param $s i32) (result i32)",
      "    (local $len i32) (local $i i32) (local $neg i32)",
      "    (local $c i32) (local $box i32) (local $cell i32) (local $pe i32)",
      "    (local $failed i32) (local $acc i64)",
      "    (local.set $failed (i32.const 0))",
      "    (local.set $acc (i64.const 0))",
      "    (local.set $len (call $__strlen (local.get $s)))",
      "    (block $exit",
      "      (if (i32.eqz (local.get $len))",
      "        (then (local.set $failed (i32.const 1)) (br $exit)))",
      "      (local.set $i (i32.const 0))",
      "      (local.set $neg (i32.const 0))",
      "      (if (i32.eq (i32.load8_u (local.get $s)) (i32.const 45))",
      "        (then",
      "          (local.set $neg (i32.const 1))",
      "          (local.set $i (i32.const 1))",
      "          (if (i32.eq (local.get $len) (i32.const 1))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))))",
      "      (block $loop_break",
      "        (loop $loop",
      "          (br_if $loop_break (i32.ge_u (local.get $i) (local.get $len)))",
      "          (local.set $c (i32.load8_u (i32.add (local.get $s) (local.get $i))))",
      "          (if (i32.lt_u (local.get $c) (i32.const 48))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (if (i32.gt_u (local.get $c) (i32.const 57))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $acc",
      "            (i64.add",
      "              (i64.mul (local.get $acc) (i64.const 10))",
      "              (i64.extend_i32_u (i32.sub (local.get $c) (i32.const 48)))))",
      "          (if (i64.gt_s (local.get $acc) (i64.shl (i64.const 1) (i64.const 31)))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "          (br $loop)))",
      "      (if (local.get $neg)",
      "        (then (local.set $acc (i64.sub (i64.const 0) (local.get $acc))))",
      "        (else",
      "          (if (i64.gt_s (local.get $acc) (i64.const 2147483647))",
      "            (then (local.set $failed (i32.const 1)) (br $exit))))))",
      "    (if (result i32) (local.get $failed)",
      "      (then",
      "        (local.set $pe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $pe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $pe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.wrap_i64 (local.get $acc)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | parseUInt8 : String -> Either ParseError UInt8. Same shape as
--   'rtParseInt32' minus the sign handling, with an i32 accumulator
--   (the running magnitude never exceeds 2559 before the > 255 check
--   fails the parse).
rtParseUInt8 :: Text
rtParseUInt8 =
  unlines
    [ "  (func $__parseUInt8 (param $s i32) (result i32)",
      "    (local $len i32) (local $i i32) (local $acc i32)",
      "    (local $c i32) (local $box i32) (local $cell i32) (local $pe i32)",
      "    (local $failed i32)",
      "    (local.set $failed (i32.const 0))",
      "    (local.set $acc (i32.const 0))",
      "    (local.set $len (call $__strlen (local.get $s)))",
      "    (block $exit",
      "      (if (i32.eqz (local.get $len))",
      "        (then (local.set $failed (i32.const 1)) (br $exit)))",
      "      (local.set $i (i32.const 0))",
      "      (block $loop_break",
      "        (loop $loop",
      "          (br_if $loop_break (i32.ge_u (local.get $i) (local.get $len)))",
      "          (local.set $c (i32.load8_u (i32.add (local.get $s) (local.get $i))))",
      "          (if (i32.lt_u (local.get $c) (i32.const 48))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (if (i32.gt_u (local.get $c) (i32.const 57))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $acc",
      "            (i32.add",
      "              (i32.mul (local.get $acc) (i32.const 10))",
      "              (i32.sub (local.get $c) (i32.const 48))))",
      "          (if (i32.gt_u (local.get $acc) (i32.const 255))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "          (br $loop))))",
      "    (if (result i32) (local.get $failed)",
      "      (then",
      "        (local.set $pe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $pe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $pe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (local.get $acc))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | showUInt32: render an unsigned 32-bit value as decimal. Mirrors
--   'rtShowI32' but skips the negative-sign branch — the input bit
--   pattern is treated as unsigned end-to-end (i32.div_u / i32.rem_u),
--   so values 2147483648..4294967295 render correctly without an
--   erroneous '-' prefix.
rtShowU32 :: Text
rtShowU32 =
  unlines
    [ "  (func $__show_u32 (param $p i32) (result i32)",
      "    (local $v i32) (local $buf i32) (local $pos i32) (local $digit i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (local.set $buf (call $__alloc (i32.const 16)))",
      "    (i32.store8 (i32.add (local.get $buf) (i32.const 15)) (i32.const 0))",
      "    (local.set $pos (i32.const 14))",
      "    (if (i32.eqz (local.get $v))",
      "      (then",
      "        (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.const 48))",
      "        (local.set $pos (i32.sub (local.get $pos) (i32.const 1))))",
      "      (else",
      "        (block $done",
      "          (loop $loop",
      "            (br_if $done (i32.eqz (local.get $v)))",
      "            (local.set $digit (i32.rem_u (local.get $v) (i32.const 10)))",
      "            (i32.store8 (i32.add (local.get $buf) (local.get $pos)) (i32.add (local.get $digit) (i32.const 48)))",
      "            (local.set $pos (i32.sub (local.get $pos) (i32.const 1)))",
      "            (local.set $v (i32.div_u (local.get $v) (i32.const 10)))",
      "            (br $loop)))))",
      "    (i32.add (local.get $buf) (i32.add (local.get $pos) (i32.const 1))))"
    ]

-- | predUInt32: Either UnderflowError UInt32. Mirrors 'rtPredU8' since
--   the underflow boundary is also 0; the only difference is that the
--   stored cell is interpreted as unsigned 32-bit, but i32.eqz / i32.sub
--   work bit-pattern-identically for u32.
rtPredU32 :: Text
rtPredU32 =
  unlines
    [ "  (func $__predUInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eqz (local.get $v))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | succUInt32: Either OverflowError UInt32. Boundary is 4294967295,
--   encoded as 'i32.const -1' (same bit pattern). On the ok path
--   '(v + 1)' wraps modulo 2^32 in i32 arithmetic — but since we already
--   checked v != 4294967295, the result is in 1..4294967295 and the
--   wrap is irrelevant.
rtSuccU32 :: Text
rtSuccU32 =
  unlines
    [ "  (func $__succUInt32 (param $p i32) (result i32)",
      "    (local $v i32) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $v (i32.load (local.get $p)))",
      "    (if (result i32) (i32.eq (local.get $v) (i32.const -1))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.add (local.get $v) (i32.const 1)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | addUInt32: Either OverflowError UInt32. Widen both operands to i64
--   (extend_i32_u, unsigned), sum at 64-bit width, compare against
--   4294967295. On the ok path 'i32.wrap_i64' truncates the low 32 bits,
--   which is exactly the in-range result.
rtAddU32 :: Text
rtAddU32 =
  unlines
    [ "  (func $__addUInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $s i64) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $s",
      "      (i64.add",
      "        (i64.extend_i32_u (i32.load (local.get $pa)))",
      "        (i64.extend_i32_u (i32.load (local.get $pb)))))",
      "    (if (result i32) (i64.gt_u (local.get $s) (i64.const 4294967295))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.wrap_i64 (local.get $s)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | subUInt32: Either UnderflowError UInt32. 'i32.lt_u' compares the
--   stored cells as unsigned; the difference is computed at i32 width
--   (the bit pattern matches u32 subtraction when a >= b).
rtSubU32 :: Text
rtSubU32 =
  unlines
    [ "  (func $__subUInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $a i32) (local $b i32) (local $ue i32) (local $box i32) (local $cell i32)",
      "    (local.set $a (i32.load (local.get $pa)))",
      "    (local.set $b (i32.load (local.get $pb)))",
      "    (if (result i32) (i32.lt_u (local.get $a) (local.get $b))",
      "      (then",
      "        (local.set $ue (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $ue) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $ue))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.sub (local.get $a) (local.get $b)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | mulUInt32: Either OverflowError UInt32. Promote both operands to
--   i64 (extend_i32_u) so the unmasked product up to (2^32-1)^2 fits,
--   compare against 4294967295.
rtMulU32 :: Text
rtMulU32 =
  unlines
    [ "  (func $__mulUInt32 (param $pa i32) (param $pb i32) (result i32)",
      "    (local $p i64) (local $oe i32) (local $box i32) (local $cell i32)",
      "    (local.set $p",
      "      (i64.mul",
      "        (i64.extend_i32_u (i32.load (local.get $pa)))",
      "        (i64.extend_i32_u (i32.load (local.get $pb)))))",
      "    (if (result i32) (i64.gt_u (local.get $p) (i64.const 4294967295))",
      "      (then",
      "        (local.set $oe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $oe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $oe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.wrap_i64 (local.get $p)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | parseUInt32 : String -> Either ParseError UInt32. Same shape as
--   'rtParseUInt8' but with an i64 accumulator so the running magnitude
--   (up to 4294967295 * 10 + 9 = 42949672959) fits before the
--   '> 4294967295' fast-fail check.
rtParseUInt32 :: Text
rtParseUInt32 =
  unlines
    [ "  (func $__parseUInt32 (param $s i32) (result i32)",
      "    (local $len i32) (local $i i32) (local $acc i64)",
      "    (local $c i32) (local $box i32) (local $cell i32) (local $pe i32)",
      "    (local $failed i32)",
      "    (local.set $failed (i32.const 0))",
      "    (local.set $acc (i64.const 0))",
      "    (local.set $len (call $__strlen (local.get $s)))",
      "    (block $exit",
      "      (if (i32.eqz (local.get $len))",
      "        (then (local.set $failed (i32.const 1)) (br $exit)))",
      "      (local.set $i (i32.const 0))",
      "      (block $loop_break",
      "        (loop $loop",
      "          (br_if $loop_break (i32.ge_u (local.get $i) (local.get $len)))",
      "          (local.set $c (i32.load8_u (i32.add (local.get $s) (local.get $i))))",
      "          (if (i32.lt_u (local.get $c) (i32.const 48))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (if (i32.gt_u (local.get $c) (i32.const 57))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $acc",
      "            (i64.add",
      "              (i64.mul (local.get $acc) (i64.const 10))",
      "              (i64.extend_i32_u (i32.sub (local.get $c) (i32.const 48)))))",
      "          (if (i64.gt_u (local.get $acc) (i64.const 4294967295))",
      "            (then (local.set $failed (i32.const 1)) (br $exit)))",
      "          (local.set $i (i32.add (local.get $i) (i32.const 1)))",
      "          (br $loop))))",
      "    (if (result i32) (local.get $failed)",
      "      (then",
      "        (local.set $pe (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $pe) (i32.const 0))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (i32.store offset=4 (local.get $cell) (local.get $pe))",
      "        (local.get $cell))",
      "      (else",
      "        (local.set $box (call $__alloc (i32.const 4)))",
      "        (i32.store (local.get $box) (i32.wrap_i64 (local.get $acc)))",
      "        (local.set $cell (call $__alloc (i32.const 8)))",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (i32.store offset=4 (local.get $cell) (local.get $box))",
      "        (local.get $cell))))"
    ]

-- | eqInt32 / eqUInt8: two boxed integers → Bool (one-slot container).
--   Int32 and UInt8 both flow as pointers to an i32 cell; UInt8 values are
--   stored masked to 0..255, so a plain i32.eq gives the same answer as
--   native u8 equality. True=0, False=1 matches declaration order in
--   `type Bool = True | False`.
rtEqI32 :: Text
rtEqI32 =
  unlines
    [ "  (func $__eq_i32 (param $a i32) (param $b i32) (result i32)",
      "    (local $cell i32)",
      "    (local.set $cell (call $__alloc (i32.const 4)))",
      "    (if (result i32) (i32.eq (i32.load (local.get $a)) (i32.load (local.get $b)))",
      "      (then",
      "        (i32.store (local.get $cell) (i32.const 0))",
      "        (local.get $cell))",
      "      (else",
      "        (i32.store (local.get $cell) (i32.const 1))",
      "        (local.get $cell))))"
    ]

rtGetArg :: Int -> Text
rtGetArg emptyOff =
  unlines
    [ "  (func $__get_arg (result i32)",
      "    (local $argv_buf i32) (local $ptrs i32)",
      "    (drop (call $args_sizes_get (i32.const 12) (i32.const 16)))",
      "    (if (result i32) (i32.lt_u (i32.load (i32.const 12)) (i32.const 2))",
      "      (then (i32.const " <> show emptyOff <> "))",
      "      (else",
      "        (local.set $argv_buf (call $__alloc (i32.load (i32.const 16))))",
      "        (local.set $ptrs (call $__alloc (i32.mul (i32.load (i32.const 12)) (i32.const 4))))",
      "        (drop (call $args_get (local.get $ptrs) (local.get $argv_buf)))",
      "        (i32.load (i32.add (local.get $ptrs) (i32.const 4))))))"
    ]

startFunc :: Text
startFunc =
  unlines
    [ "  (func $_start (export \"_start\")",
      "    (local $input i32)",
      "    (local $right_box i32)",
      "    (local.set $input (call $__get_arg))",
      -- Wrap input in `Right input` (tag=1, one field) before handing to user's
      -- main. Layout matches CCon emit on WASM: alloc(4 * (1 + nFields)),
      -- i32 tag at offset 0, fields at offsets 4..  Tag is a raw i32 at offset
      -- 0; field is the boxed value pointer at offset 4.
      "    (local.set $right_box (call $__alloc (i32.const 8)))",
      "    (i32.store (local.get $right_box) (i32.const 1))",
      "    (i32.store offset=4 (local.get $right_box) (local.get $input))",
      "    (drop (call $" <> mangle "main" <> " (local.get $right_box))))"
    ]

-- ════════════════════════════════════════════════════════════════════════════
-- User declarations
-- ════════════════════════════════════════════════════════════════════════════

emitDecl :: WasmCtx -> CDecl -> Text
emitDecl ctx = \case
  -- TCO-wrapped body. WASM parameters double as mutable locals, so a
  -- 'CContinue' can rebind them directly; we only need extra @$__k@
  -- locals to stage new values so that cross-parameter reads see the
  -- old bindings. The whole body runs inside @(loop $tco_top ...)@, and
  -- @br $tco_top@ restarts it instead of recursing.
  CFunDef nm args (CLoop body) ->
    let paramSet = Set.fromList args
        localCtx = ctx {wParams = paramSet, wLocalExprs = Map.empty}
        wasmParams = T.intercalate " " (map (\a -> "(param $" <> mangle a <> " i32)") args)
        locals = collectLocals body
        tcoTemps =
          T.concat
            [ "\n    (local $__k" <> show (i :: Int) <> " i32)"
            | i <- [0 .. length args - 1]
            ]
     in "  (func $"
          <> mangle nm
          <> " "
          <> wasmParams
          <> " (result i32)"
          <> locals
          <> tcoTemps
          <> "\n    (loop $tco_top (result i32) "
          <> emitTailWat localCtx args body
          <> "))"
  CFunDef nm args body ->
    let paramSet = Set.fromList args
        localCtx = ctx {wParams = paramSet, wLocalExprs = Map.empty}
        wasmParams = T.intercalate " " (map (\a -> "(param $" <> mangle a <> " i32)") args)
        locals = collectLocals body
     in "  (func $"
          <> mangle nm
          <> " "
          <> wasmParams
          <> " (result i32)"
          <> locals
          <> "\n    "
          <> emitExpr localCtx body
          <> ")"
  CValDef nm rhs ->
    let localCtx = ctx {wParams = Set.empty, wLocalExprs = Map.empty}
        locals = collectLocals rhs
     in "  (func $"
          <> mangle nm
          <> " (result i32)"
          <> locals
          <> "\n    "
          <> emitExpr localCtx rhs
          <> ")"

-- | Emit @body@ in tail position under a @(loop $tco_top ...)@.
-- 'CContinue' rebinds the loop's parameters and jumps back to the loop
-- head; any other tail shape produces an @i32@ value that becomes the
-- function's result. 'CCase' chains structurally so each arm is itself
-- emitted in tail form — either a value or a @br@ terminator.
emitTailWat :: WasmCtx -> [Text] -> CExpr -> Text
emitTailWat ctx0 params = go ctx0
  where
    go :: WasmCtx -> CExpr -> Text
    go ctx = \case
      CContinue newArgs ->
        let temps = ["$__k" <> show (i :: Int) | i <- [0 .. length newArgs - 1]]
            evals =
              [ "(local.set " <> t <> " " <> emitExpr ctx a <> ")"
              | (t, a) <- zip temps newArgs
              ]
            rebinds =
              [ "(local.set $" <> mangle p <> " (local.get " <> t <> "))"
              | (p, t) <- zip params temps
              ]
         in T.intercalate " " (evals <> rebinds <> ["(br $tco_top)"])
      CCase scrut alts ->
        let sorted = sortWith (\(t, _, _) -> t) alts
            scrutCode = emitExpr ctx scrut
         in "(block (result i32) (local.set $__scrut "
              <> scrutCode
              <> ") "
              <> buildTailChain ctx sorted
              <> ")"
      -- 'CRow' / 'CRowCase' share the runtime layout with one-field
      -- 'CCon' / 'CCase' (tag at offset 0, value at offset 4) so we
      -- can lower them through the same emit machinery; the tag width
      -- is 32 bits in both cases, just hash- vs. position-derived.
      CRow tag v -> go ctx (CCon (fromIntegral tag) [v])
      CRowCase scrut alts ->
        go ctx (CCase scrut [(fromIntegral t, [v], b) | (t, v, b) <- alts])
      other -> emitExpr ctx other

    buildTailChain :: WasmCtx -> [(Int, [Text], CExpr)] -> Text
    buildTailChain _ [] = "(unreachable)"
    buildTailChain ctx [(_, vars, body)] =
      armEntry vars <> go (bindVars ctx vars) body
    buildTailChain ctx ((tag, vars, body) : rest) =
      "(if (result i32) (i32.eq (i32.load (local.get $__scrut)) (i32.const "
        <> show tag
        <> ")) (then "
        <> armEntry vars
        <> go (bindVars ctx vars) body
        <> ") (else "
        <> buildTailChain ctx rest
        <> "))"

-- ════════════════════════════════════════════════════════════════════════════
-- Expressions
-- ════════════════════════════════════════════════════════════════════════════

emitExpr :: WasmCtx -> CExpr -> Text
emitExpr ctx = \case
  CString s ->
    let offset = fromMaybe (error $ "string not in pool: " <> show s) (Map.lookup s ctx.wStringPool)
     in "(i32.const " <> show offset <> ")"
  CVar n
    | Just expr <- Map.lookup n ctx.wLocalExprs -> expr
    | n `Set.member` ctx.wParams ->
        "(local.get $" <> mangle n <> ")"
    | n `Set.member` ctx.wValDefs ->
        "(call $" <> mangle n <> ")"
    | n `Set.member` ctx.wFunDefs ->
        let idx = fromMaybe 0 (Map.lookup n ctx.wTableMap)
         in "(i32.const " <> show idx <> ")"
    | otherwise ->
        "(i32.const 0)"
  CBuiltIn _ ->
    "(i32.const 0)" -- invariant: not a standalone term; dispatched from CCall
  CIntLit n _ ->
    let n32 = fromInteger n :: Int32
     in "(call $__box_i32 (i32.const " <> show n32 <> "))"
  CCon tag fields ->
    let conLocal = "$__con_" <> show ctx.wConDepth
        nestedCtx = ctx {wConDepth = ctx.wConDepth + 1}
        nSlots = 1 + length fields
        storeTag = "(i32.store (local.tee " <> conLocal <> " (call $__alloc (i32.const " <> show (nSlots * 4 :: Int) <> "))) (i32.const " <> show tag <> "))"
        storeFields =
          [ "(i32.store offset=" <> show (i * 4 :: Int) <> " (local.get " <> conLocal <> ") " <> emitExpr nestedCtx fld <> ")"
          | (fld, i) <- zip fields [1 :: Int ..]
          ]
     in "(block (result i32) " <> T.intercalate " " (storeTag : storeFields <> ["(local.get " <> conLocal <> ")"]) <> ")"
  -- 'CRow' / 'CRowCase' share the runtime layout with one-field
  -- 'CCon' / 'CCase' (tag at offset 0, value at offset 4) so we can
  -- lower them through the same emit machinery.
  CRow tag v -> emitExpr ctx (CCon (fromIntegral tag) [v])
  CRowCase scrut alts ->
    emitExpr ctx (CCase scrut [(fromIntegral t, [v], b) | (t, v, b) <- alts])
  CCase scrut alts ->
    emitCaseExpr ctx scrut alts
  CCall f xs ->
    case f of
      CBuiltIn "IO.Stdout.print"
        | [x] <- xs ->
            "(call $__print " <> emitExpr ctx x <> ")"
      CBuiltIn name
        | name == "showInt32" || name == "showUInt8",
          [x] <- xs ->
            "(call $__show_i32 " <> emitExpr ctx x <> ")"
      CBuiltIn "showUInt32"
        | [x] <- xs ->
            "(call $__show_u32 " <> emitExpr ctx x <> ")"
      CBuiltIn "predInt32"
        | [x] <- xs ->
            "(call $__predInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn "predUInt8"
        | [x] <- xs ->
            "(call $__predUInt8 " <> emitExpr ctx x <> ")"
      CBuiltIn "predUInt32"
        | [x] <- xs ->
            "(call $__predUInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn "succInt32"
        | [x] <- xs ->
            "(call $__succInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn "succUInt8"
        | [x] <- xs ->
            "(call $__succUInt8 " <> emitExpr ctx x <> ")"
      CBuiltIn "succUInt32"
        | [x] <- xs ->
            "(call $__succUInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn name
        | name == "eqInt32" || name == "eqUInt8" || name == "eqUInt32",
          [a, b] <- xs ->
            "(call $__eq_i32 " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CBuiltIn name
        | name == "addInt32" || name == "addUInt8" || name == "addUInt32" || name == "subInt32" || name == "subUInt8" || name == "subUInt32" || name == "mulUInt8" || name == "mulUInt32" || name == "mulInt32",
          [a, b] <- xs ->
            let fn = case name of
                  "addInt32" -> "$__addInt32"
                  "addUInt8" -> "$__addUInt8"
                  "addUInt32" -> "$__addUInt32"
                  "subInt32" -> "$__subInt32"
                  "subUInt8" -> "$__subUInt8"
                  "subUInt32" -> "$__subUInt32"
                  "mulInt32" -> "$__mulInt32"
                  "mulUInt32" -> "$__mulUInt32"
                  _ -> "$__mulUInt8"
             in "(call " <> fn <> " " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CBuiltIn "negInt32"
        | [x] <- xs ->
            "(call $__negInt32 " <> emitExpr ctx x <> ")"
      CBuiltIn "splitOnFirst"
        | [a, b] <- xs ->
            "(call $__splitOnFirst " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CBuiltIn name
        | name == "parseInt32" || name == "parseUInt8" || name == "parseUInt32",
          [x] <- xs ->
            let fn = case name of
                  "parseInt32" -> "$__parseInt32"
                  "parseUInt32" -> "$__parseUInt32"
                  _ -> "$__parseUInt8"
             in "(call " <> fn <> " " <> emitExpr ctx x <> ")"
      CBuiltIn "concatString"
        | [a, b] <- xs ->
            "(call $__concat " <> emitExpr ctx a <> " " <> emitExpr ctx b <> ")"
      CBuiltIn n ->
        error ("WASM codegen: unknown builtin '" <> n <> "' reached CCall (typecheck should have rejected it)")
      CVar n
        | n `Set.member` ctx.wFunDefs ->
            "(call $" <> mangle n <> " " <> T.intercalate " " (map (emitExpr ctx) xs) <> ")"
      _ ->
        let arity = length xs
         in "(call_indirect (type $arity_"
              <> show arity
              <> ") "
              <> T.intercalate " " (map (emitExpr ctx) xs)
              <> " "
              <> emitExpr ctx f
              <> ")"
  CLoop _ -> error "WASM codegen: CLoop survived untcoProgram (pipeline bug)"
  CContinue _ -> error "WASM codegen: CContinue survived untcoProgram (pipeline bug)"

-- | Emit a case expression as nested @if\/else@ in WAT.
--   Stores the scrutinee in @$__scrut@, extracts the tag from offset 0,
--   materialises each bound variable into its own WASM local on arm
--   entry (pre-declared by 'collectLocals'), and then runs the body.
--   This keeps outer-arm bindings safe when the inner body overwrites
--   @$__scrut@ with its own scrutinee.
emitCaseExpr :: WasmCtx -> CExpr -> [(Int, [Text], CExpr)] -> Text
emitCaseExpr ctx scrut alts =
  let sorted = sortWith (\(t, _, _) -> t) alts
      scrutCode = emitExpr ctx scrut
   in "(block (result i32) (local.set $__scrut " <> scrutCode <> ") " <> buildChain sorted <> ")"
  where
    buildChain [] = "(unreachable)"
    buildChain [(_, vars, body)] =
      armEntry vars <> emitExpr (bindVars ctx vars) body
    buildChain ((tag, vars, body) : rest) =
      "(if (result i32) (i32.eq (i32.load (local.get $__scrut)) (i32.const "
        <> show tag
        <> ")) (then "
        <> armEntry vars
        <> emitExpr (bindVars ctx vars) body
        <> ") (else "
        <> buildChain rest
        <> "))"

-- | Emit @local.set@ for each arm-bound variable, pulling values out of
-- the current @$__scrut@ into their pre-declared @$v_<name>@ slots
-- before any nested 'CCase' gets a chance to overwrite @$__scrut@.
armEntry :: [Text] -> Text
armEntry vars =
  T.concat
    [ "(local.set $"
        <> mangle v
        <> " (i32.load offset="
        <> show (i * 4 :: Int)
        <> " (local.get $__scrut))) "
    | (v, i) <- zip vars [1 :: Int ..]
    ]

-- | Register each arm-bound name in 'wLocalExprs' as a bare
-- @(local.get $v_<name>)@. The slot was already written by 'armEntry',
-- so every subsequent use of the binder reads its own local (not the
-- shared @$__scrut@).
bindVars :: WasmCtx -> [Text] -> WasmCtx
bindVars ctx vars =
  let entries =
        [ (v, "(local.get $" <> mangle v <> ")")
        | v <- vars
        ]
   in ctx {wLocalExprs = foldl' (\m (k, e) -> Map.insert k e m) ctx.wLocalExprs entries}

-- | Determine which locals a function body needs and emit their declarations.
-- Each 'CCase' arm's bindings are materialised into a per-binding named
-- local on arm entry (see 'bindVars'); nested 'CCase's would clobber each
-- other if bindings stayed as inline @i32.load@ expressions against a
-- shared @$__scrut@. Pre-declaring @$v_<name>@ for every bound name means
-- the inner case is free to overwrite @$__scrut@ without corrupting outer
-- arm bindings.
collectLocals :: CExpr -> Text
collectLocals body =
  let depth = maxConDepth body
      conLocals = T.concat ["\n    (local $__con_" <> show i <> " i32)" | i <- [0 .. depth - 1]]
      ns = hasCCase body
      bindLocals =
        T.concat
          [ "\n    (local $" <> mangle v <> " i32)"
          | v <- Set.toAscList (caseBoundVars body)
          ]
   in conLocals
        <> bindLocals
        <> (if ns then "\n    (local $__scrut i32)" else "")

-- | Every case-arm binding name reachable from @e@. Used by 'collectLocals'
-- to pre-declare a WASM local per binding so arm-entry can materialise
-- values into their own slots, immune to later 'CCase' scrutinee writes.
caseBoundVars :: CExpr -> Set Text
caseBoundVars = \case
  CCase s alts ->
    caseBoundVars s
      <> foldMap (\(_, vs, b) -> Set.fromList vs <> caseBoundVars b) alts
  CRowCase s alts ->
    caseBoundVars s
      <> foldMap (\(_, v, b) -> Set.singleton v <> caseBoundVars b) alts
  CRow _ v -> caseBoundVars v
  CCall f xs -> caseBoundVars f <> foldMap caseBoundVars xs
  CCon _ fs -> foldMap caseBoundVars fs
  CLoop b -> caseBoundVars b
  CContinue xs -> foldMap caseBoundVars xs
  _ -> mempty

-- | Compute the maximum CCon nesting depth in an expression.
maxConDepth :: CExpr -> Int
maxConDepth = \case
  CCon _ fields -> 1 + foldl' max 0 (map maxConDepth fields)
  CRow _ v -> 1 + maxConDepth v
  CCase s alts -> max (maxConDepth s) (foldl' max 0 [maxConDepth b | (_, _, b) <- alts])
  CRowCase s alts -> max (maxConDepth s) (foldl' max 0 [maxConDepth b | (_, _, b) <- alts])
  CCall f xs -> foldl' max (maxConDepth f) (map maxConDepth xs)
  _ -> 0

hasCCase :: CExpr -> Bool
hasCCase = \case
  CCase {} -> True
  CRowCase {} -> True
  CCall f xs -> hasCCase f || any hasCCase xs
  _ -> False

-- ════════════════════════════════════════════════════════════════════════════
-- Name mangling
-- ════════════════════════════════════════════════════════════════════════════

-- | All names get @v_@ prefix (including @main@ → @v_main@),
--   because @_start@ is the WASI entry point.
mangle :: Text -> Text
mangle t =
  let ok c = Char.isAlphaNum c || c == '_' || c == '\''
      body = T.map (\c -> if ok c then c else '_') t
   in "v_" <> body
